import sys
import json

def ftag(t):
    return lambda node: node.tag == t

def ustr(s):
    if sys.version_info < (3, 0):
        #py2
        try:
            return unicode(s).encode('utf-8')
        except:
            return s
    else:
        return str(s)

class TableJSONEncoder(json.JSONEncoder):
    def default(self, obj):
        if hasattr(obj, '__json__'):
            return obj.__json__()
        return json.JSONEncoder.default(self, obj)

#!/usr/bin/env python
from flask import render_template, Blueprint

from project import db   # pragma: no cover
from project.models import Person   # pragma: no cover
import random

# config
home_blueprint = Blueprint(
    'home', __name__,
    template_folder='templates'
)   # pragma: no cover


# routes
# use decorators to link the function to a url
@home_blueprint.route('/', methods=['GET', 'POST'])   # pragma: no cover
def home():
    error = None
    current_person_count = db.session.query(Person).count()
    # random sample of 10 people, else all.
    if current_person_count >= 10:
        ids = random.sample(xrange(current_person_count), 10)
        persons = []
        i = 0
        for p in db.session.query(Person):
            if i in ids:
                persons.append(p)
            i += 1
    else:
        persons = db.session.query(Person).all()
    return render_template(
        'index.html', persons=persons, error=error)

