import threading

import boto3

import objects.glob
from common.log import logUtils as log


def getClient():
    return objects.glob.s3Connections[threading.get_ident()]


def getWriteReplayBucketName():
    try:
        return objects.glob.db.fetch("SELECT `name` FROM s3_replay_buckets WHERE max_score_id IS NULL LIMIT 1")["name"]
    except TypeError:
        return None


def getReadReplayBucketName(scoreID):
    origScoreID = scoreID
    r = objects.glob.db.fetch(
        "SELECT `name`, max_score_id FROM s3_replay_buckets WHERE max_score_id IS NOT NULL "
        "ORDER BY abs(max_score_id - %s) LIMIT 1",
        (scoreID,)
    )
    if r is not None and scoreID <= r["max_score_id"]:
        log.debug("s3 replay buckets resolve: {} -> {}".format(origScoreID, r["name"]))
        return r["name"]
    scoreInBucketsRange = objects.glob.db.fetch(
        "SELECT COUNT(*) AS cnt FROM s3_replay_buckets WHERE max_score_id >= %s",
        (scoreID,)
    )["cnt"] > 0
    if not scoreInBucketsRange:
        # ScoreID not found, check if write bucket exists, otherwise create it.
        writeBucketName = getWriteReplayBucketName()
        if writeBucketName is not None:
            log.debug("s3 replay buckets resolve: {} -> WRITE BUCKET".format(origScoreID))
            return writeBucketName
        bucketCreated = None
        while bucketCreated is None:
            scoreFoundInBucketsRange = objects.glob.db.fetch(
                "SELECT COUNT(*) AS cnt FROM s3_replay_buckets WHERE max_score_id >= %s",
                (scoreID,)
            )["cnt"] > 0
            if scoreFoundInBucketsRange:
                break
            bucketCreated = objects.glob.db.runQuery(
                "INSERT INTO s3_replay_buckets `score_range_end`, `max_score_id`, `name`, `creation_time` "
                "VALUES ((SELECT IFNULL(max(`score_range_end`, %s), %s) FROM s3_replay_buckets), "
                "(SELECT IFNULL(max(`score_range_end`), %s) FROM s3_replay_buckets), CONCAT(CURDATE(), '_', CAST(COUNT(*) AS CHAR) ), "
                "UNIX_TIMESTAMP())",
                (scoreID, scoreID,)
            )
    log.debug("s3 replay buckets resolve: {} -> WRITE BUCKET".format(origScoreID))
    return getWriteReplayBucketName()


def clientFactory():
    log.info("Created a new S3 client for thread {}".format(threading.get_ident()))
    return boto3.Session(region_name=objects.glob.conf["S3_REGION"]).client(
        "s3",
        endpoint_url=objects.glob.conf["S3_ENDPOINT_URL"],
        aws_access_key_id=objects.glob.conf["S3_ACCESS_KEY_ID"],
        aws_secret_access_key=objects.glob.conf["S3_SECRET_ACCESS_KEY"]
    )

